BEGIN; CREATE TABLE centros(id INTEGER PRIMARY KEY, centro); INSERT INTO centros VALUES(1,'xxx'); CREATE TABLE usuarios(id INTEGER PRIMARY KEY, nombre, apellidos, idcentro INTEGER); INSERT INTO usuarios VALUES(1,'a','aa',1); INSERT INTO usuarios VALUES(2,'b','bb',1); INSERT INTO usuarios VALUES(3,'c','cc',NULL); CREATE INDEX idcentro ON usuarios(idcentro); COMMIT; CREATE TABLE _result AS SELECT usuarios.id, usuarios.nombre, centros.centro FROM usuarios LEFT OUTER JOIN centros ON usuarios.idcentro=centros.id ORDER BY usuarios.id;